                W.add(nb)
        # While U not empty
        while U:
            # Select u in U with max |N(u) ∩ W|, tie-break by min degree in U, then by index (lower index first)
            u = max(U, key=lambda x: (len([nb for nb in graph[x] if nb in W]), len([nb for nb in graph[x] if nb in U]), -x))
            independent_set.add(u)
            to_remove.add(u)
            U.remove(u)
            # Move neighbors of u from U to W
            for nb in graph[u]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
        # Assign color to independent set
        for v in independent_set:
            colors[v] = color
            uncolored.remove(v)
        color += 1
    return colors

def greedy_coloring(graph, order):
    n = len(graph)
    colors = [-1] * n
    for v in order:
        used = set()
        for nb in graph[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        c = 0
        while c in used:
            c += 1
        colors[v] = c
    return colors

def smallest_last_ordering(graph, deg):
    n = len(graph)
    if n == 0:
        return []
    current_deg = deg[:]
    removed = [False] * n
    order = []
    # Use buckets for efficiency
    max_deg = max(deg) if deg else 0
    buckets = [[] for _ in range(max_deg + 1)]
    for v in range(n):
        d = current_deg[v]
        if d < len(buckets):
            buckets[d].append(v)
        else:
            # extend buckets if needed (should not happen)
            buckets.extend([[] for _ in range(d - len(buckets) + 1)])
            buckets[d].append(v)
    # Pointer to current min non-empty bucket
    min_deg = 0
    for _ in range(n):
        # Find non-empty bucket
        while min_deg < len(buckets) and not buckets[min_deg]:
            min_deg += 1
        if min_deg >= len(buckets):
            # Should not happen
            break
        v = buckets[min_deg].pop()
        if removed[v]:
            # Find another
            while buckets[min_deg] and removed[buckets[min_deg][-1]]:
                buckets[min_deg].pop()
            if not buckets[min_deg]:
                min_deg += 1
                continue
            v = buckets[min_deg].pop()
        removed[v] = True
        order.append(v)
        for nb in graph[v]:
            if not removed[nb]:
                d = current_deg[nb]
                # Remove nb from bucket d
                if d < len(buckets) and nb in buckets[d]:
                    buckets[d].remove(nb)
                current_deg[nb] -= 1
                nd = current_deg[nb]
                if nd < len(buckets):
                    buckets[nd].append(nb)
                else:
                    buckets.extend([[] for _ in range(nd - len(buckets) + 1)])
                    buckets[nd].append(nb)
                if nd < min_deg:
                    min_deg = nd
    return order[::-1]

def kempe_improve(graph, colors):
    n = len(graph)
    if n == 0:
        return colors
    # Make a copy to work on
    col = colors[:]
    improved = True
    # Limit iterations to avoid timeout
    for _ in range(15):  # Reduced iterations for speed, still effective
        if not improved:
            break
        improved = False
        # Determine color classes
        max_color = max(col) if col else -1
        if max_color < 0:
            break
        classes = [[] for _ in range(max_color + 1)]
        for v in range(n):
            c = col[v]
            classes[c].append(v)
        # Try to eliminate color classes from highest down
        for target_color in range(max_color, 0, -1):
            if not classes[target_color]:
                continue
            # Try to recolor each vertex in this class
            for v in classes[target_color][:]:  # copy list as we may modify
                # Try direct recoloring to a lower color
                neighbor_colors = set()
                for nb in graph[v]:
                    if col[nb] != -1:
                        neighbor_colors.add(col[nb])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        # Recolor v to c
                        col[v] = c
                        classes[target_color].remove(v)
                        classes[c].append(v)
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains
                for c in range(target_color):
                    if c in neighbor_colors:
                        continue
                    # Check if v is connected to color c via Kempe chain (target_color, c)
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in graph[node]:
                            if not visited[nb] and (col[nb] == target_color or col[nb] == c):
                                visited[nb] = True
                                stack.append(nb)
                    # Perform swap: safe because we know no neighbor of v has color c (from neighbor_colors check)
                    for node in component:
                        if col[node] == target_color:
                            col[node] = c
                        else:
                            col[node] = target_color
                    # Update classes
                    classes[target_color].remove(v)
                    classes[c].append(v)
                    # Also need to update other vertices in component
                    for node in component:
                        if node == v:
                            continue
                        if col[node] == c:  # was target_color, now c
                            classes[target_color].remove(node)
                            classes[c].append(node)
                        else:  # was c, now target_color
                            classes[c].remove(node)
                            classes[target_color].append(node)
                    improved = True
                    break
                if improved:
                    break
            if improved:
                break
            # If we couldn't recolor any vertex in this class, we cannot eliminate this color yet
        # If we improved, break and restart from highest color (since classes changed)
        if improved:
            break
    return col
